let godsChosen=0;
let currentTab='blacksmith',selected='medium-infantry';
const all=Object.values(groups).flatMap(sections=>sections.flatMap(section=>section.nodes));
const get=id=>all.find(node=>node.id===id);
const state=node=>node.requiredGods>godsChosen?'locked':node.level===node.max?'mastered':node.parent&&get(node.parent).level<get(node.parent).max?'locked':'available';
const roman=['I','II','III'];
function updateCounts(){for(const tab of Object.keys(groups)){const nodes=groups[tab].flatMap(s=>s.nodes);document.getElementById('count-'+tab).textContent=nodes.filter(n=>state(n)==='mastered').length+' / '+nodes.length;}document.getElementById('total-complete').textContent=all.filter(n=>state(n)==='mastered').length;}
function render(){
 document.getElementById('trees').innerHTML=groups[currentTab].map((group,index)=>`<section class="section ${group.independent?'independent':''}"><div class="section-heading"><span class="section-icon" aria-hidden="true">${group.icon}</span><h2>${group.title}</h2><span class="rule"></span><span class="section-meta">${group.nodes.length} ADVANCEMENTS</span></div><p class="section-description">${group.description}</p>${group.divine?`<div class="god-control"><label for="gods-chosen">Gods chosen <span>(preview)</span></label><select id="gods-chosen">${[0,1,2,3].map(count=>`<option value="${count}" ${count===godsChosen?'selected':''}>${count===0?'No gods chosen':count===1?'First god chosen':count===2?'Second god chosen':'Third god chosen'}</option>`).join('')}</select><small>Set your god-selection progress to preview availability. Lowering it resets affected divine researches.</small></div>`:''}<div class="tree-scroll" aria-label="${group.title} research tree, scroll horizontally on small screens" tabindex="0"><div class="tree-inner"><div class="tier-labels">${(group.tiers||['I · FOUNDATIONS','II · ADVANCEMENTS','III · MASTERY']).map(label=>`<span>${label}</span>`).join('')}</div><div class="tree-canvas" data-group="${index}"><svg class="connector-layer" aria-hidden="true"></svg><div class="tree-grid">${group.nodes.map((node,i)=>{const status=state(node);return `<button class="node ${status} ${node.id===selected?'selected':''}" data-id="${node.id}" aria-pressed="${node.id===selected}" aria-label="${node.name}, ${node.level} of ${node.max}, ${status}"><span class="node-header">${node.name}<span class="small-roman">${group.independent?`Lv. ${node.level}`:roman[i%3]}</span></span><span class="node-content"><span class="sprite ${node.icon}" aria-hidden="true"></span><span class="node-progress"><span class="node-value">${node.level} / ${node.max}</span><span class="progress-track"><span style="width:${node.level/node.max*100}%"></span></span></span><span class="node-action" aria-hidden="true">${status==='mastered'?'✓':status==='locked'?'▴':'⚗'}</span></span></button>`}).join('')}</div></div></div></div></section>`).join('');
 updateCounts();renderDetails();requestAnimationFrame(drawBranches);
}
function drawBranches(){document.querySelectorAll('.tree-canvas').forEach(canvas=>{const group=groups[currentTab][Number(canvas.dataset.group)];const svg=canvas.querySelector('svg'),base=canvas.getBoundingClientRect();svg.setAttribute('viewBox',`0 0 ${base.width} ${base.height}`);svg.innerHTML=group.nodes.filter(n=>n.parent).map(node=>{const from=canvas.querySelector(`[data-id="${node.parent}"]`),to=canvas.querySelector(`[data-id="${node.id}"]`);if(!from||!to)return '';const a=from.getBoundingClientRect(),b=to.getBoundingClientRect(),x=a.right-base.left,y=a.top+a.height/2-base.top,x2=b.left-base.left,y2=b.top+b.height/2-base.top,mid=(x+x2)/2;const ready=state(get(node.parent))==='mastered'?' ready':'';const path=`M ${x} ${y} H ${mid} V ${y2} H ${x2-5}`;return `<path class="connector-shadow${ready}" d="${path}"/><path class="connector${ready}" d="${path}"/><path d="M ${x2-7} ${y2-5} L ${x2} ${y2} L ${x2-7} ${y2+5} Z" fill="${ready?'#789846':'#ba8e4f'}" stroke="${ready?'#456138':'#72512c'}" stroke-width="1.5"/>`}).join('');});}
function renderDetails(){const node=get(selected),status=state(node),section=groups[currentTab].find(s=>s.nodes.includes(node)),tier=section.nodes.indexOf(node)%3;document.getElementById('detail-tier').textContent=section.independent?`LEVEL ${node.level} / ${node.max}`:'TIER '+roman[tier];document.getElementById('detail-icon').className='sprite '+node.icon;document.getElementById('detail-state').textContent=status==='mastered'?'✓ RESEARCH MASTERED':status==='locked'?'◇ RESEARCH LOCKED':'◆ AVAILABLE TO RESEARCH';document.getElementById('detail-name').textContent=node.name;document.getElementById('detail-description').textContent=node.description;document.getElementById('detail-effect').textContent=section.unitBonuses?`Level ${node.level} bonus: +${node.level*2}% offensive power, +${node.level*2}% defensive power, +${node.level*2}% travel speed. ${node.level<node.max?`Next level: +${(node.level+1)*2}% to each.`:`Maximum level reached.`}`:node.effect;document.getElementById('detail-level').textContent=`${node.level} / ${node.max}`;document.getElementById('detail-fill').style.width=node.level/node.max*100+'%';document.getElementById('prerequisites').innerHTML=node.requiredGods?`Requires<br><strong>${godsChosen>=node.requiredGods?'✓':'◇'} Choose your ${['first','second','third'][node.requiredGods-1]} god · ${godsChosen} chosen</strong>`:node.parent?`Requires<br><strong>${state(get(node.parent))==='mastered'?'✓':'◇'} ${get(node.parent).name} · ${get(node.parent).level}/${get(node.parent).max}</strong>`:'<strong>✓ No prior research required</strong>';const button=document.getElementById('research-button');button.disabled=status!=='available';button.textContent=status==='mastered'?'✓ Upgrade mastered':status==='locked'?'Complete prerequisite':'⚒ Research upgrade';document.getElementById('detail-help').textContent=status==='mastered'?'This advancement has reached its full potential.':status==='locked'?(node.requiredGods?`Choose your ${['first','second','third'][node.requiredGods-1]} god to unlock.`:'Master the previous advancement to unlock.'):'Advance one level toward mastery.';}
function setGodProgress(count){if(!Number.isInteger(count)||count<0||count>3)throw new Error('God count must be from 0 to 3.');godsChosen=count;all.filter(n=>n.requiredGods>count).forEach(n=>n.level=0);render();document.getElementById('announcement').textContent=`${count} gods chosen. Divine research availability updated.`;}
document.getElementById('trees').addEventListener('change',event=>{if(event.target.id==='gods-chosen'){setGodProgress(Number(event.target.value));document.getElementById('gods-chosen').focus();}});
document.getElementById('trees').addEventListener('click',event=>{const button=event.target.closest('[data-id]');if(!button)return;selected=button.dataset.id;document.querySelectorAll('.node').forEach(el=>{const active=el.dataset.id===selected;el.classList.toggle('selected',active);el.setAttribute('aria-pressed',String(active));});renderDetails();});
function switchTab(tab){currentTab=tab;selected=tab==='blacksmith'?'medium-infantry':'irrigation-1';document.querySelectorAll('[data-tab]').forEach(button=>{const active=button.dataset.tab===tab;button.classList.toggle('active',active);button.setAttribute('aria-selected',String(active));button.tabIndex=active?0:-1;});document.getElementById('research-panel').setAttribute('aria-labelledby','tab-'+tab);render();}
document.querySelectorAll('[data-tab]').forEach(button=>{button.addEventListener('click',()=>switchTab(button.dataset.tab));button.addEventListener('keydown',event=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;event.preventDefault();const target=event.key==='Home'?'blacksmith':event.key==='End'?'library':currentTab==='blacksmith'?'library':'blacksmith';switchTab(target);document.getElementById('tab-'+target).focus();});});
function researchUpgrade(id){const node=get(id);if(!node)throw new Error('Unknown advancement.');if(state(node)!=='available')throw new Error('This advancement cannot be researched yet or is already mastered.');const tab=Object.keys(groups).find(key=>groups[key].some(section=>section.nodes.includes(node)));if(currentTab!==tab)switchTab(tab);selected=id;node.level++;render();document.getElementById('announcement').textContent=`${node.name} upgraded to ${node.level} of ${node.max}.${state(node)==='mastered'?' Research mastered.':''}`;if(state(node)==='mastered')document.querySelector(`[data-id="${node.id}"]`).focus();return {id:node.id,level:node.level,max:node.max,status:state(node)};}
document.getElementById('research-button').addEventListener('click',()=>researchUpgrade(selected));
window.addEventListener('resize',drawBranches);if(document.fonts)document.fonts.ready.then(drawBranches);render();
if(document.modelContext?.registerTool){const lifecycle=new AbortController();const tools=[{name:'read_research_tree',description:'Read the current sample research progress and prerequisites for both buildings.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>all.map(node=>({id:node.id,name:node.name,level:node.level,max:node.max,prerequisite:node.parent,requiredGods:node.requiredGods||0,godsChosen,status:state(node)}))},{name:'research_upgrade',description:'Advance one available research upgrade by one level and show it in the page. Sample progress resets on reload.',inputSchema:{type:'object',properties:{id:{type:'string',enum:all.map(node=>node.id)}},required:['id'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!input||typeof input.id!=='string'||Object.keys(input).some(key=>key!=='id'))throw new Error('Supply only a valid advancement id.');return researchUpgrade(input.id);}}];for(const tool of tools){try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
